"use client";

import { Slice } from "@tiptap/pm/model";
import { EditorState } from "@tiptap/pm/state";
import { EditorContent, useEditor } from "@tiptap/react";
import { type ComponentProps, type CSSProperties, useEffect, useMemo, useRef, useState } from "react";
import type { MarkdownEditorKnobStyle } from "@/components/control-ui/knob-contracts/markdown-editor-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { Textarea } from "@/components/control-ui/ui/textarea";
import { MarkdownEditorContext, useMarkdownEditor } from "./markdown-editor/context";
import { createMarkdownCodec, hasMarkdownContent, markdownExtensions, requiresMarkdownSource } from "./markdown-editor/extensions";
import type { MarkdownImageUploader } from "./markdown-editor/uploads";
import { useImageUploads } from "./markdown-editor/use-image-uploads";

export type MarkdownEditorStatus = { isEmpty: boolean; hasPendingUploads: boolean };
export type MarkdownEditorProps = Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "style"> & {
  value?: string;
  defaultValue?: string;
  onValueChange?: (markdown: string) => void;
  disabled?: boolean;
  onUploadImage?: MarkdownImageUploader;
  maxImageBytes?: number;
  onStatusChange?: (status: MarkdownEditorStatus) => void;
  style?: CSSProperties & MarkdownEditorKnobStyle;
};

export function MarkdownEditor({
  value,
  defaultValue = "",
  onValueChange,
  disabled = false,
  onUploadImage,
  maxImageBytes = 10 * 1024 * 1024,
  onStatusChange,
  children,
  className,
  ...props
}: MarkdownEditorProps) {
  const [internalValue, setInternalValue] = useState(defaultValue);
  const markdown = value ?? internalValue;
  const [sourceMode, setSourceMode] = useState(false);
  const [contentAttributes, setContentAttributes] = useState<Record<string, string>>({ role: "textbox", "aria-multiline": "true" });
  const [codec] = useState(createMarkdownCodec);
  const sourceRequired = useMemo(() => requiresMarkdownSource(markdown, codec), [markdown, codec]);
  const source = sourceMode || sourceRequired;
  const lastValue = useRef(markdown);
  const [extensions] = useState(markdownExtensions);
  const handlers = useRef<{ upload: (files: File[], position?: number) => void; cancelAll: () => void } | null>(null);

  function setMarkdown(next: string) {
    lastValue.current = next;
    setInternalValue(next);
    onValueChange?.(next);
  }

  const editor = useEditor({
    extensions,
    immediatelyRender: false,
    shouldRerenderOnTransaction: false,
    content: sourceRequired ? "" : markdown,
    contentType: "markdown",
    editable: !disabled,
    onUpdate: ({ editor: currentEditor }) => setMarkdown(currentEditor.getMarkdown()),
    editorProps: {
      attributes: contentAttributes,
      handlePaste: (view, event) => {
        if (disabled) return false;
        const files = Array.from(event.clipboardData?.files ?? []);
        if (onUploadImage && files.length > 0) {
          event.preventDefault();
          handlers.current?.upload(files);
          return true;
        }
        const text = event.clipboardData?.getData("text/plain");
        if (!text || event.clipboardData?.getData("text/html") || requiresMarkdownSource(text, codec)) return false;
        const document = view.state.schema.nodeFromJSON(codec.parse(text));
        event.preventDefault();
        view.dispatch(view.state.tr.replaceSelection(Slice.maxOpen(document.content)).scrollIntoView());
        return true;
      },
      handleDrop: (view, event, _slice, moved) => {
        const files = Array.from(event.dataTransfer?.files ?? []);
        if (moved || !onUploadImage || disabled || files.length === 0) return false;
        event.preventDefault();
        const position = view.posAtCoords({ left: event.clientX, top: event.clientY })?.pos;
        handlers.current?.upload(files, position);
        return true;
      },
    },
  });
  const imageUploads = useImageUploads(editor, onUploadImage, maxImageBytes);
  useEffect(() => {
    handlers.current = imageUploads;
  });

  useEffect(() => {
    if (!editor) return;
    editor.setEditable(!disabled, false);
  }, [editor, disabled]);

  useEffect(() => {
    if (!editor) return;
    const externalReset = lastValue.current !== markdown;
    if (externalReset) handlers.current?.cancelAll();
    if (source) {
      lastValue.current = markdown;
      return;
    }
    if (editor.getMarkdown() !== markdown) {
      editor.commands.setContent(markdown, { contentType: "markdown", emitUpdate: false });
      if (externalReset) {
        editor.view.updateState(EditorState.create({ schema: editor.schema, doc: editor.state.doc, plugins: editor.state.plugins }));
        editor.view.dispatch(editor.state.tr);
      }
    }
    lastValue.current = markdown;
  }, [editor, markdown, source]);

  const isEmpty = source ? markdown.trim() === "" : !hasMarkdownContent(codec.parse(markdown));
  const hasPendingUploads = imageUploads.uploads.length > 0;
  useEffect(() => {
    onStatusChange?.({ isEmpty, hasPendingUploads });
  }, [onStatusChange, isEmpty, hasPendingUploads]);

  return (
    <MarkdownEditorContext
      value={{
        editor,
        disabled,
        source,
        markdown,
        sourceRequired,
        setSource: setSourceMode,
        setMarkdown,
        setContentAttributes,
        canUpload: Boolean(onUploadImage),
        ...imageUploads,
      }}
    >
      <div
        data-control-ui="markdown-editor"
        data-control-family="markdown-editor"
        data-slot="root"
        data-disabled={disabled ? "" : undefined}
        className={cn("min-w-0", className)}
        {...props}
      >
        {children}
      </div>
    </MarkdownEditorContext>
  );
}

export type MarkdownEditorContentProps = {
  label: string;
  placeholder?: string;
  autoFocus?: boolean;
  className?: string;
};

export function MarkdownEditorContent({ label, placeholder, autoFocus = false, className }: MarkdownEditorContentProps) {
  const { editor, disabled, source, sourceRequired, markdown, setMarkdown, setContentAttributes } = useMarkdownEditor();
  useEffect(() => {
    setContentAttributes({
      role: "textbox",
      "aria-multiline": "true",
      "aria-label": label,
      "aria-disabled": String(disabled),
      "data-placeholder": placeholder ?? "",
    });
  }, [setContentAttributes, label, disabled, placeholder]);

  useEffect(() => {
    if (editor && autoFocus && !source && !disabled) editor.commands.focus("end");
  }, [editor, autoFocus, source, disabled]);

  if (source || !editor)
    return (
      <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="source" className={className}>
        {sourceRequired ? (
          <p role="status">This content uses Markdown that is only available in source mode. Its source is preserved.</p>
        ) : null}
        <Textarea
          aria-label={label}
          placeholder={placeholder}
          value={markdown}
          disabled={disabled || !editor}
          onChange={(event) => setMarkdown(event.target.value)}
          rows={5}
        />
      </div>
    );
  return (
    <EditorContent
      editor={editor}
      data-control-ui="markdown-editor"
      data-control-family="markdown-editor"
      data-slot="content"
      className={className}
    />
  );
}

import type { Editor } from "@tiptap/core";
import { createContext, useContext } from "react";
import type { MarkdownImageUpload } from "./uploads";

export type MarkdownEditorContextValue = {
  editor: Editor | null;
  disabled: boolean;
  source: boolean;
  markdown: string;
  sourceRequired: boolean;
  setSource: (source: boolean) => void;
  setMarkdown: (value: string) => void;
  setContentAttributes: (attributes: Record<string, string>) => void;
  canUpload: boolean;
  uploads: MarkdownImageUpload[];
  upload: (files: File[], position?: number) => void;
  retryUpload: (id: string) => void;
  removeUpload: (id: string) => void;
  uploadError: string | null;
};

export const MarkdownEditorContext = createContext<MarkdownEditorContextValue | null>(null);

export function useMarkdownEditor() {
  const context = useContext(MarkdownEditorContext);
  if (!context) throw new Error("Markdown editor parts require a MarkdownEditor parent.");
  return context;
}

import { type JSONContent, Node } from "@tiptap/core";
import Image from "@tiptap/extension-image";
import { TaskItem, TaskList } from "@tiptap/extension-list";
import Paragraph from "@tiptap/extension-paragraph";
import { TableKit } from "@tiptap/extension-table";
import { Markdown, MarkdownManager } from "@tiptap/markdown";
import StarterKit from "@tiptap/starter-kit";

export function isEditorUrl(value: string, image = false): boolean {
  if (!value || /[\s\\]/.test(value) || Array.from(value).some((character) => character.charCodeAt(0) < 32)) return false;
  if (value.startsWith("/") && !value.startsWith("//")) return true;
  if (!image && value.startsWith("#")) return true;
  try {
    const url = new URL(value);
    return ["https:", "http:", ...(image ? [] : ["mailto:"])].includes(url.protocol);
  } catch {
    return false;
  }
}

const SafeImage = Image.extend({
  renderMarkdown: (node) => {
    const src = String(node.attrs?.src ?? "").replace(/[()]/g, (character) => `\\${character}`);
    const alt = String(node.attrs?.alt ?? "").replace(/[\\[\]]/g, (character) => `\\${character}`);
    const title = String(node.attrs?.title ?? "").replace(/[\\"]/g, (character) => `\\${character}`);
    return title ? `![${alt}](${src} "${title}")` : `![${alt}](${src})`;
  },
  addAttributes() {
    return {
      ...this.parent?.(),
      src: {
        default: null,
        parseHTML: (element) => {
          const src = element.getAttribute("src") ?? "";
          return isEditorUrl(src, true) ? src : null;
        },
        renderHTML: (attributes) => ({ src: isEditorUrl(attributes.src ?? "", true) ? attributes.src : undefined }),
      },
    };
  },
});

const MarkdownParagraph = Paragraph.extend({
  parseMarkdown: (token, helpers) => {
    const content = helpers.parseInline(token.tokens ?? []);
    const first = content[0];
    const empty = content.length === 1 && first?.type === "text" && ["&nbsp;", "\u00a0"].includes(first.text ?? "");
    return helpers.createNode("paragraph", undefined, empty ? [] : content);
  },
});

export const ImageUpload = Node.create({
  name: "imageUpload",
  group: "block",
  atom: true,
  selectable: true,
  addAttributes: () => ({ id: { default: null }, name: { default: "Image" } }),
  renderHTML: ({ node }) => ["div", { "data-image-upload": "", role: "status" }, `Image: ${node.attrs.name}`],
  renderMarkdown: () => "",
});

export function markdownExtensions() {
  return [
    StarterKit.configure({
      underline: false,
      paragraph: false,
      link: { openOnClick: false, isAllowedUri: (url) => isEditorUrl(url) },
    }),
    MarkdownParagraph,
    SafeImage.configure({ allowBase64: false, inline: true }),
    TaskList,
    TaskItem.configure({ nested: true, HTMLAttributes: { "data-type": "taskItem" } }),
    TableKit.configure({ table: { resizable: false } }),
    ImageUpload,
    Markdown,
  ];
}

export function createMarkdownCodec() {
  return new MarkdownManager({ extensions: markdownExtensions() });
}

const supportedTokens = new Set([
  "space",
  "code",
  "heading",
  "hr",
  "blockquote",
  "list",
  "list_item",
  "paragraph",
  "text",
  "escape",
  "link",
  "image",
  "strong",
  "em",
  "codespan",
  "br",
  "del",
  "table",
  "def",
  "taskList",
  "taskItem",
]);

function unsupportedToken(value: unknown): boolean {
  if (Array.isArray(value)) return value.some(unsupportedToken);
  if (typeof value !== "object" || value === null) return false;
  if ("type" in value && typeof value.type === "string") {
    if (!supportedTokens.has(value.type)) return true;
    if (
      (value.type === "image" || value.type === "link") &&
      "href" in value &&
      typeof value.href === "string" &&
      !isEditorUrl(value.href, value.type === "image")
    )
      return true;
  }
  return Object.values(value).some(unsupportedToken);
}

export function requiresMarkdownSource(markdown: string, codec: MarkdownManager): boolean {
  return unsupportedToken(codec.instance.lexer(markdown));
}

export function hasMarkdownContent(document: JSONContent): boolean {
  if (document.type === "image") return true;
  if (document.type === "text" && document.text?.trim()) return true;
  return document.content?.some(hasMarkdownContent) ?? false;
}

"use client";

import { useEditorState } from "@tiptap/react";
import {
  BoldIcon,
  CodeIcon,
  Heading2Icon,
  ImageIcon,
  ItalicIcon,
  LinkIcon,
  ListChecksIcon,
  ListIcon,
  ListOrderedIcon,
  QuoteIcon,
  RedoIcon,
  SquareCodeIcon,
  StrikethroughIcon,
  UndoIcon,
} from "lucide-react";
import { type ReactNode, useId, useRef, useState } from "react";
import { ChatComposerAttachment, ChatComposerAttachments } from "@/components/control-ui/chat-composer-attachment";
import { Button } from "@/components/control-ui/ui/button";
import { Input } from "@/components/control-ui/ui/input";
import { Label } from "@/components/control-ui/ui/label";
import { Popover, PopoverContent, PopoverTitle, PopoverTrigger } from "@/components/control-ui/ui/popover";
import { Toolbar, ToolbarButton, ToolbarSeparator } from "@/components/control-ui/ui/toolbar";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/control-ui/ui/tooltip";
import { useMarkdownEditor } from "./context";
import { isEditorUrl } from "./extensions";
import { markdownImageTypes } from "./uploads";

export function MarkdownEditorToolbar({ children }: { children?: ReactNode }) {
  const { editor, disabled, source, sourceRequired, setSource, uploads } = useMarkdownEditor();
  const state = useEditorState({
    editor,
    selector: ({ editor: current }) => ({
      bold: current?.isActive("bold"),
      italic: current?.isActive("italic"),
      strike: current?.isActive("strike"),
      code: current?.isActive("code"),
      heading: current?.isActive("heading", { level: 2 }),
      bulletList: current?.isActive("bulletList"),
      orderedList: current?.isActive("orderedList"),
      taskList: current?.isActive("taskList"),
      blockquote: current?.isActive("blockquote"),
      codeBlock: current?.isActive("codeBlock"),
      undo: current?.can().undo(),
      redo: current?.can().redo(),
    }),
  });
  const actions = [
    { label: "Bold", Icon: BoldIcon, active: state?.bold, run: () => editor?.chain().focus().toggleBold().run() },
    { label: "Italic", Icon: ItalicIcon, active: state?.italic, run: () => editor?.chain().focus().toggleItalic().run() },
    { label: "Strikethrough", Icon: StrikethroughIcon, active: state?.strike, run: () => editor?.chain().focus().toggleStrike().run() },
    { label: "Inline code", Icon: CodeIcon, active: state?.code, run: () => editor?.chain().focus().toggleCode().run() },
    { label: "Heading", Icon: Heading2Icon, active: state?.heading, run: () => editor?.chain().focus().toggleHeading({ level: 2 }).run() },
    { label: "Bullet list", Icon: ListIcon, active: state?.bulletList, run: () => editor?.chain().focus().toggleBulletList().run() },
    {
      label: "Numbered list",
      Icon: ListOrderedIcon,
      active: state?.orderedList,
      run: () => editor?.chain().focus().toggleOrderedList().run(),
    },
    { label: "Task list", Icon: ListChecksIcon, active: state?.taskList, run: () => editor?.chain().focus().toggleTaskList().run() },
    { label: "Quote", Icon: QuoteIcon, active: state?.blockquote, run: () => editor?.chain().focus().toggleBlockquote().run() },
    { label: "Code block", Icon: SquareCodeIcon, active: state?.codeBlock, run: () => editor?.chain().focus().toggleCodeBlock().run() },
  ];
  return (
    <TooltipProvider>
      <Toolbar aria-label="Markdown formatting" className="flex w-full flex-wrap">
        {actions.map(({ label, Icon, active, run }) => (
          <Tooltip key={label}>
            <TooltipTrigger
              render={
                <ToolbarButton
                  type="button"
                  iconOnly
                  aria-label={label}
                  aria-pressed={Boolean(active)}
                  disabled={disabled || source || !editor}
                  onMouseDown={(event) => event.preventDefault()}
                  onClick={run}
                />
              }
            >
              <Icon aria-hidden="true" />
            </TooltipTrigger>
            <TooltipContent>{label}</TooltipContent>
          </Tooltip>
        ))}
        <MarkdownEditorLink />
        <MarkdownEditorImage />
        <ToolbarSeparator />
        <ToolbarButton
          type="button"
          iconOnly
          aria-label="Undo"
          disabled={disabled || source || !state?.undo}
          onClick={() => editor?.chain().focus().undo().run()}
        >
          <UndoIcon aria-hidden="true" />
        </ToolbarButton>
        <ToolbarButton
          type="button"
          iconOnly
          aria-label="Redo"
          disabled={disabled || source || !state?.redo}
          onClick={() => editor?.chain().focus().redo().run()}
        >
          <RedoIcon aria-hidden="true" />
        </ToolbarButton>
        <ToolbarButton
          type="button"
          aria-pressed={source}
          disabled={disabled || !editor || sourceRequired || uploads.length > 0}
          onClick={() => setSource(!source)}
        >
          Markdown source
        </ToolbarButton>
        {children}
      </Toolbar>
    </TooltipProvider>
  );
}

export function MarkdownEditorLink() {
  const { editor, disabled, source } = useMarkdownEditor();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const inputId = useId();
  const valid = isEditorUrl(url.trim());
  function apply() {
    if (!valid || disabled || source) return;
    editor?.chain().focus().extendMarkRange("link").setLink({ href: url.trim() }).run();
    setOpen(false);
  }
  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        if (next) setUrl(editor?.getAttributes("link").href ?? "");
      }}
    >
      <PopoverTrigger disabled={disabled || source || !editor} render={<ToolbarButton type="button" iconOnly aria-label="Edit link" />}>
        <LinkIcon aria-hidden="true" />
      </PopoverTrigger>
      <PopoverContent
        className="grid gap-3"
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            event.stopPropagation();
            apply();
          }
        }}
      >
        <PopoverTitle>Edit link</PopoverTitle>
        <Label htmlFor={inputId}>URL</Label>
        <Input id={inputId} value={url} onChange={(event) => setUrl(event.target.value)} placeholder="https://example.com" />
        <div className="flex gap-2">
          <Button type="button" disabled={!valid || disabled} onClick={apply}>
            Apply link
          </Button>
          <Button
            type="button"
            variant="ghost"
            disabled={disabled}
            onClick={() => {
              editor?.chain().focus().extendMarkRange("link").unsetLink().run();
              setOpen(false);
            }}
          >
            Remove link
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export function MarkdownEditorImage() {
  const { editor, disabled, source, canUpload, upload } = useMarkdownEditor();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState("");
  const [alt, setAlt] = useState("");
  const inputId = useId();
  const altId = useId();
  const fileInput = useRef<HTMLInputElement>(null);
  const valid = isEditorUrl(url.trim(), true);
  function insert() {
    if (!valid || disabled || source) return;
    editor?.chain().focus().setImage({ src: url.trim(), alt }).run();
    setOpen(false);
    setUrl("");
    setAlt("");
  }
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger disabled={disabled || source || !editor} render={<ToolbarButton type="button" iconOnly aria-label="Insert image" />}>
        <ImageIcon aria-hidden="true" />
      </PopoverTrigger>
      <PopoverContent
        className="grid gap-3"
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            event.stopPropagation();
            insert();
          }
        }}
      >
        <PopoverTitle>Insert image</PopoverTitle>
        <Label htmlFor={inputId}>Image URL</Label>
        <Input id={inputId} value={url} onChange={(event) => setUrl(event.target.value)} placeholder="https://example.com/image.png" />
        <Label htmlFor={altId}>Image description</Label>
        <Input id={altId} value={alt} onChange={(event) => setAlt(event.target.value)} />
        <Button type="button" disabled={!valid || disabled} onClick={insert}>
          Insert image
        </Button>
        {canUpload ? (
          <>
            <input
              ref={fileInput}
              type="file"
              accept={markdownImageTypes.join(",")}
              multiple
              hidden
              onChange={(event) => {
                upload(Array.from(event.target.files ?? []));
                event.target.value = "";
                setOpen(false);
              }}
            />
            <Button type="button" variant="ghost" disabled={disabled} onClick={() => fileInput.current?.click()}>
              Upload images
            </Button>
          </>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

export function MarkdownEditorUploads() {
  const { uploads, uploadError, retryUpload, removeUpload, disabled } = useMarkdownEditor();
  return (
    <>
      {uploadError ? <p role="alert">{uploadError}</p> : null}
      {uploads.length > 0 ? (
        <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="uploads">
          <ChatComposerAttachments label="Image uploads">
            {uploads.map((item) => (
              <ChatComposerAttachment
                key={item.id}
                file={item.file}
                status={item.status}
                progress={item.progress}
                onRemove={disabled ? undefined : () => removeUpload(item.id)}
                removeLabel={`Remove ${item.file.name}`}
              />
            ))}
          </ChatComposerAttachments>
          {uploads
            .filter((item) => item.status === "error")
            .map((item) => (
              <div key={item.id} role="alert" className="flex items-center gap-2">
                <span>
                  {item.file.name}: {item.error}
                </span>
                <Button type="button" size="xs" disabled={disabled} onClick={() => retryUpload(item.id)}>
                  Retry upload
                </Button>
              </div>
            ))}
        </div>
      ) : null}
    </>
  );
}

import type { Editor } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import { isEditorUrl } from "./extensions";

export type MarkdownImage = { url: string; alt?: string; title?: string };
export type MarkdownImageUploader = (
  file: File,
  options: { signal: AbortSignal; onProgress: (progress: number) => void },
) => Promise<MarkdownImage>;
export type MarkdownImageUpload = {
  id: string;
  file: File;
  status: "uploading" | "error";
  progress?: number;
  error?: string;
};

export function findImageUpload(document: ProseMirrorNode, id: string) {
  let position: number | undefined;
  document.descendants((node, pos) => {
    if (node.type.name === "imageUpload" && node.attrs.id === id) position = pos;
  });
  return position;
}

export function completeImageUpload(editor: Editor, id: string, image: MarkdownImage, fallbackAlt: string) {
  if (!isEditorUrl(image.url, true)) throw new Error("The upload must return a permanent HTTP(S) or root-relative image URL.");
  const position = findImageUpload(editor.state.doc, id);
  if (position === undefined) return;
  const imageType = editor.schema.nodes.image;
  const paragraphType = editor.schema.nodes.paragraph;
  if (!imageType || !paragraphType) throw new Error("Image uploads require image and paragraph nodes.");
  const node = imageType.create({ src: image.url, alt: image.alt ?? fallbackAlt, title: image.title ?? null });
  editor.view.dispatch(
    editor.state.tr.replaceWith(position, position + 1, paragraphType.create(null, node)).setMeta("addToHistory", false),
  );
}

export const markdownImageTypes = ["image/png", "image/jpeg", "image/gif", "image/webp", "image/avif"];

import type { Editor } from "@tiptap/core";
import { useEffect, useId, useRef, useState } from "react";
import { completeImageUpload, findImageUpload, type MarkdownImageUpload, type MarkdownImageUploader, markdownImageTypes } from "./uploads";

export function useImageUploads(editor: Editor | null, uploader: MarkdownImageUploader | undefined, maxImageBytes: number) {
  const [uploads, setUploads] = useState<MarkdownImageUpload[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const uploadPrefix = useId();
  const nextId = useRef(0);
  const jobs = useRef(new Map<string, { file: File; controller: AbortController }>());

  function discard(id: string) {
    jobs.current.get(id)?.controller.abort();
    jobs.current.delete(id);
    setUploads((current) => current.filter((item) => item.id !== id));
  }

  function cancelAll() {
    for (const job of jobs.current.values()) job.controller.abort();
    jobs.current.clear();
    setUploads([]);
  }

  useEffect(() => {
    const activeJobs = jobs.current;
    return () => {
      for (const job of activeJobs.values()) job.controller.abort();
      activeJobs.clear();
    };
  }, []);

  useEffect(() => {
    if (!editor) return;
    const prune = () => {
      for (const id of jobs.current.keys()) {
        if (findImageUpload(editor.state.doc, id) === undefined) {
          jobs.current.get(id)?.controller.abort();
          jobs.current.delete(id);
          setUploads((current) => current.filter((item) => item.id !== id));
        }
      }
    };
    editor.on("update", prune);
    return () => {
      editor.off("update", prune);
    };
  }, [editor]);

  async function run(id: string, file: File) {
    if (!editor || !uploader) return;
    const controller = new AbortController();
    jobs.current.set(id, { file, controller });
    setUploads((current) => [...current.filter((item) => item.id !== id), { id, file, status: "uploading" }]);
    try {
      const image = await uploader(file, {
        signal: controller.signal,
        onProgress: (progress) => {
          if (controller.signal.aborted || !Number.isFinite(progress)) return;
          setUploads((current) =>
            current.map((item) => (item.id === id ? { ...item, progress: Math.max(0, Math.min(100, progress)) } : item)),
          );
        },
      });
      if (controller.signal.aborted || editor.isDestroyed) return;
      completeImageUpload(editor, id, image, file.name);
      discard(id);
    } catch (error) {
      if (controller.signal.aborted) return;
      setUploads((current) =>
        current.map((item) =>
          item.id === id
            ? {
                ...item,
                status: "error",
                error: error instanceof Error ? error.message : "Image upload failed.",
              }
            : item,
        ),
      );
    }
  }

  function upload(files: File[], position?: number) {
    if (!editor || !uploader || !editor.isEditable) return;
    setUploadError(null);
    let insertAt = position ?? editor.state.selection.to;
    for (const file of files) {
      if (!markdownImageTypes.includes(file.type) || file.size > maxImageBytes) {
        setUploadError(`Choose a PNG, JPEG, GIF, WebP or AVIF image up to ${Math.round(maxImageBytes / 1024 / 1024)} MB.`);
        continue;
      }
      const id = `${uploadPrefix}-${nextId.current++}`;
      editor
        .chain()
        .focus()
        .insertContentAt(insertAt, { type: "imageUpload", attrs: { id, name: file.name } })
        .run();
      insertAt = editor.state.selection.to;
      void run(id, file);
    }
  }

  function removeUpload(id: string) {
    discard(id);
    if (!editor) return;
    const position = findImageUpload(editor.state.doc, id);
    if (position !== undefined) editor.view.dispatch(editor.state.tr.delete(position, position + 1).setMeta("addToHistory", false));
  }

  function retryUpload(id: string) {
    const job = jobs.current.get(id);
    if (job) {
      job.controller.abort();
      void run(id, job.file);
    }
  }

  return { uploads, uploadError, upload, retryUpload, removeUpload, cancelAll };
}

@layer components {
  :where([data-control-family="markdown-editor"][data-slot="root"]) {
    --cui-markdown-editor-background: var(--background);
    --cui-markdown-editor-foreground: var(--foreground);
    --cui-markdown-editor-border-width: var(--control-rim-width);
    --cui-markdown-editor-border-color: var(--border);
    --cui-markdown-editor-radius: var(--radius-panel);
    --cui-markdown-editor-padding: calc(var(--spacing) * 3);
    --cui-markdown-editor-min-height: calc(var(--spacing) * 32);
    --cui-markdown-editor-max-height: 60dvh;
    --cui-markdown-editor-gap: calc(var(--spacing) * 3);
    --cui-markdown-editor-muted-foreground: var(--muted-foreground);
    --cui-markdown-editor-code-background: var(--muted);
    color: var(--cui-markdown-editor-foreground);
    background: var(--cui-markdown-editor-background);
    border: var(--cui-markdown-editor-border-width) solid var(--cui-markdown-editor-border-color);
    border-radius: var(--cui-markdown-editor-radius);
    overflow: clip;
    font-size: var(--text-body);
    line-height: var(--leading-relaxed);
  }
  :where([data-control-family="markdown-editor"][data-slot="content"] .tiptap) {
    min-block-size: var(--cui-markdown-editor-min-height);
    max-block-size: var(--cui-markdown-editor-max-height);
    overflow: auto;
    padding: var(--cui-markdown-editor-padding);
    overflow-wrap: anywhere;
    white-space: pre-wrap;
  }
  :where([data-control-family="markdown-editor"] .tiptap:focus-visible) {
    outline: 2px solid var(--ring);
    outline-offset: -2px;
  }
  :where([data-control-family="markdown-editor"][data-slot="source"]),
  :where([data-control-family="markdown-editor"][data-slot="uploads"]) {
    padding: var(--cui-markdown-editor-padding);
  }
  :where([data-control-family="markdown-editor"] .tiptap > * + *) {
    margin-block-start: var(--cui-markdown-editor-gap);
  }
  :where([data-control-family="markdown-editor"] .tiptap:has(> p:only-child > br:only-child))::before {
    content: attr(data-placeholder);
    color: var(--cui-markdown-editor-muted-foreground);
    pointer-events: none;
    float: inline-start;
    block-size: 0;
  }
  :where([data-control-family="markdown-editor"] .tiptap h1) {
    font-size: var(--text-heading-2);
    font-weight: var(--font-weight-semibold);
  }
  :where([data-control-family="markdown-editor"] .tiptap h2) {
    font-size: var(--text-heading-3);
    font-weight: var(--font-weight-semibold);
  }
  :where([data-control-family="markdown-editor"] .tiptap :is(h3, h4, h5, h6)) {
    font-size: var(--text-heading-4);
    font-weight: var(--font-weight-semibold);
  }
  :where([data-control-family="markdown-editor"] .tiptap strong) {
    font-weight: var(--font-weight-semibold);
  }
  :where([data-control-family="markdown-editor"] .tiptap em) {
    font-style: italic;
  }
  :where([data-control-family="markdown-editor"] .tiptap s) {
    text-decoration: line-through;
  }
  :where([data-control-family="markdown-editor"] .tiptap a) {
    text-decoration: underline;
    color: var(--primary);
  }
  :where([data-control-family="markdown-editor"] .tiptap ul) {
    list-style: disc;
    padding-inline-start: calc(var(--spacing) * 6);
  }
  :where([data-control-family="markdown-editor"] .tiptap ol) {
    list-style: decimal;
    padding-inline-start: calc(var(--spacing) * 6);
  }
  :where([data-control-family="markdown-editor"] .tiptap ul[data-type="taskList"]) {
    list-style: none;
    padding-inline-start: 0;
  }
  :where([data-control-family="markdown-editor"] .tiptap li[data-type="taskItem"]) {
    display: flex;
    align-items: baseline;
    gap: var(--cui-markdown-editor-gap);
  }
  :where([data-control-family="markdown-editor"] .tiptap li[data-type="taskItem"] > div) {
    flex: 1;
    min-inline-size: 0;
  }
  :where([data-control-family="markdown-editor"] .tiptap blockquote) {
    border-inline-start: var(--cui-markdown-editor-border-width) solid var(--cui-markdown-editor-border-color);
    padding-inline-start: var(--cui-markdown-editor-padding);
    color: var(--cui-markdown-editor-muted-foreground);
  }
  :where([data-control-family="markdown-editor"] .tiptap :is(code, pre)) {
    font-family: var(--font-mono);
    background: var(--cui-markdown-editor-code-background);
    border-radius: var(--radius-sm);
  }
  :where([data-control-family="markdown-editor"] .tiptap pre) {
    padding: var(--cui-markdown-editor-padding);
    overflow: auto;
  }
  :where([data-control-family="markdown-editor"] .tiptap img[src]) {
    display: block;
    max-inline-size: 100%;
    block-size: auto;
    border-radius: var(--radius-sm);
  }
  :where([data-control-family="markdown-editor"] .tiptap .ProseMirror-selectednode) {
    outline: 2px solid var(--ring);
  }
  :where([data-control-family="markdown-editor"] .tiptap [data-image-upload]) {
    padding: var(--cui-markdown-editor-padding);
    border: var(--cui-markdown-editor-border-width) dashed var(--cui-markdown-editor-border-color);
    color: var(--cui-markdown-editor-muted-foreground);
  }
  :where([data-control-family="markdown-editor"] .tiptap table) {
    border-collapse: collapse;
    inline-size: 100%;
  }
  :where([data-control-family="markdown-editor"] .tiptap :is(td, th)) {
    border: var(--cui-markdown-editor-border-width) solid var(--cui-markdown-editor-border-color);
    padding: var(--cui-markdown-editor-padding);
  }
}

